node-loop-001.example:
```js
const fs = require('node:fs');

console.log('1: start (sync)');

// Offloaded to the OS/thread pool; the callback is queued for later.
fs.readFile(__filename, () => {
  console.log('3: file read finished (callback)');
});

console.log('2: end of script (sync) — runs before the I/O callback');
// Output: 1, 2, 3 — the thread never blocked on the read.
```

node-loop-002.example:
```js
// Illustrates which phase each callback belongs to.
setTimeout(() => console.log('timers phase: setTimeout'), 0);
setImmediate(() => console.log('check phase: setImmediate'));
Promise.resolve().then(() => console.log('microtask: drained between phases'));
process.nextTick(() => console.log('nextTick: drained before microtasks'));
console.log('sync: runs first');
// sync -> nextTick -> microtask -> (timers/check order varies at top level)
```

node-loop-mcq-001.example:
```js
const fs = require('node:fs');

fs.readFile(__filename, () => {
  // Scheduled from inside an I/O (poll-phase) callback:
  setTimeout(() => console.log('timeout'), 0); // timers phase = next loop
  setImmediate(() => console.log('immediate')); // check phase = this loop
});
// Always prints: immediate, then timeout.
```

node-loop-003.example:
```js
console.log('1: sync start');

process.nextTick(() => console.log('3: nextTick — after current op, before the loop continues'));

Promise.resolve().then(() => console.log('4: microtask — after nextTick'));

console.log('2: sync end');
// Output order: 1, 2, 3, 4
```

node-loop-mcq-002.example:
```js
// ❌ DANGER (do not run): never yields, starves all I/O.
// function recursive() { process.nextTick(recursive); }
// recursive();

// ✅ Use setImmediate to yield to the event loop each iteration.
let n = 0;
function safe() {
  if (n++ >= 3) return;
  console.log('iteration', n);
  setImmediate(safe); // lets the poll phase (I/O) run between iterations
}
safe();
```

node-loop-004.example:
```js
console.log('sync');
setImmediate(() => console.log('setImmediate — next loop iteration (check phase)'));
process.nextTick(() => console.log('nextTick — sooner: before the loop continues'));
// Output: sync, nextTick, setImmediate
```

node-loop-005.example:
```js
const fs = require('node:fs');

console.log('scheduling a read; the loop will park in the poll phase until it completes');
fs.readFile(__filename, () => {
  console.log('poll phase delivered the I/O event and ran this callback');
});
// With nothing else scheduled, Node sleeps in poll (0% CPU) awaiting the read.
```

node-loop-mcq-003.example:
```js
// Top-level (not inside an I/O callback): order is NOT guaranteed.
setTimeout(() => console.log('timeout'), 0);
setImmediate(() => console.log('immediate'));
// Could print timeout->immediate or immediate->timeout depending on startup timing.
```

node-loop-006.example:
```js
console.log('1: sync');
setTimeout(() => console.log('3: setTimeout(…,0) — a later timers phase'), 0);
Promise.resolve().then(() => console.log('2: microtask runs before the timer'));
console.log('1.5: more sync, still before the timeout');
// Output: 1, 1.5, 2, 3
```

node-mod-mcq-001.example:
```js
// thing.js — ❌ reassigning `exports` breaks the link to module.exports
// exports = { hello: false };          // require('./thing') -> {}

// ✅ Either mutate exports...
exports.hello = false;                   // require -> { hello: false }
// ✅ ...or replace module.exports directly
// module.exports = { hello: false };    // require -> { hello: false }
console.log(module.exports);
```

node-mod-002.example:
```js
// Core modules are cached too: requiring the same id returns the SAME object.
const os1 = require('node:os');
const os2 = require('node:os');
console.log(os1 === os2); // true — second require returns the cached exports

// Your own modules behave the same: their code runs once, result is reused.
console.log(Object.keys(require.cache).length, 'modules currently cached');
```

node-mod-003.example:
```js
// require.resolve runs the same algorithm but returns the path instead of loading.
console.log(require.resolve('node:path')); // 'node:path' (core module wins)
console.log(require.resolve('./'));         // resolves this dir's index/main to a file path
// A bare name like require.resolve('some-pkg') would search node_modules upward.
```

node-mod-004.example:
```js
// ESM (.mjs or "type": "module")
import { fileURLToPath } from 'node:url';
import { dirname } from 'node:path';

// Modern Node: import.meta.dirname / import.meta.filename exist directly.
// Portable fallback derives them from import.meta.url:
const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
console.log(__dirname, __filename);
```

node-mod-mcq-003.example:
```js
// cjs.cjs:  module.exports = { name: 'exported', value: 42 };

// app.mjs (ESM):
import cjs from './cjs.cjs'; // default import = the whole module.exports object
console.log(cjs.name, cjs.value); // 'exported' 42
```

node-mod-005.example:
```js
// a.mjs — top-level await is allowed only in ES modules.
export const five = await Promise.resolve(5);

const res = await fetch('https://example.com');
export const ok = res.ok;

console.log('module finished initializing:', five, ok);
```

node-mod-006.example:
```js
function greet(name) {
  return `Hello, ${name}!`;
}

// Only runs when executed directly: `node file.js`, not when required.
if (require.main === module) {
  console.log(greet('CLI user'));
}

module.exports = { greet }; // still reusable via require('./file')
```
